create extension if not exists pgcrypto;
create table if not exists public.lines(id uuid primary key default gen_random_uuid(),name text not null unique,area text,standard_members integer not null default 0 check(standard_members>=0),active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.stations(id uuid primary key default gen_random_uuid(),line_id uuid not null references public.lines(id) on delete cascade,name text not null,position_name text,active boolean not null default true,created_at timestamptz not null default now(),unique(line_id,name));
create table if not exists public.members(id uuid primary key default gen_random_uuid(),reg_code text not null unique,name text not null,status text not null default 'PERMANENT' check(status in('PERMANENT','KONTRAK','MAGANG')),shift text,home_line_id uuid references public.lines(id) on delete set null,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.member_skills(id uuid primary key default gen_random_uuid(),member_id uuid not null references public.members(id) on delete cascade,station_id uuid not null references public.stations(id) on delete cascade,skill_level integer not null default 0 check(skill_level between 0 and 6),training_date date,certified boolean not null default false,updated_by uuid references auth.users(id) on delete set null,updated_at timestamptz not null default now(),unique(member_id,station_id));
create table if not exists public.skill_history(id uuid primary key default gen_random_uuid(),member_id uuid not null references public.members(id) on delete cascade,station_id uuid not null references public.stations(id) on delete cascade,old_level integer not null default 0,new_level integer not null check(new_level between 0 and 6),training_date date,updated_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create table if not exists public.manpower_changes(id uuid primary key default gen_random_uuid(),work_date date not null default current_date,shift text,line_id uuid not null references public.lines(id) on delete restrict,station_id uuid not null references public.stations(id) on delete restrict,absent_member_id uuid references public.members(id) on delete set null,replacement_member_id uuid not null references public.members(id) on delete restrict,reason text not null default 'Member tidak masuk',notes text,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create index if not exists idx_stations_line on public.stations(line_id); create index if not exists idx_member_skills_station on public.member_skills(station_id); create index if not exists idx_member_skills_member on public.member_skills(member_id); create index if not exists idx_changes_date_line on public.manpower_changes(work_date,line_id);
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
drop trigger if exists members_updated_at on public.members; create trigger members_updated_at before update on public.members for each row execute function public.set_updated_at();
drop trigger if exists member_skills_updated_at on public.member_skills; create trigger member_skills_updated_at before update on public.member_skills for each row execute function public.set_updated_at();
alter table public.lines enable row level security; alter table public.stations enable row level security; alter table public.members enable row level security; alter table public.member_skills enable row level security; alter table public.skill_history enable row level security; alter table public.manpower_changes enable row level security;
do $$ declare t text; begin foreach t in array array['lines','stations','members','member_skills','skill_history','manpower_changes'] loop execute format('drop policy if exists %I_select_auth on public.%I',t,t); execute format('drop policy if exists %I_insert_auth on public.%I',t,t); execute format('drop policy if exists %I_update_auth on public.%I',t,t); execute format('drop policy if exists %I_delete_auth on public.%I',t,t); execute format('create policy %I_select_auth on public.%I for select to authenticated using(true)',t,t); execute format('create policy %I_insert_auth on public.%I for insert to authenticated with check(true)',t,t); execute format('create policy %I_update_auth on public.%I for update to authenticated using(true) with check(true)',t,t); execute format('create policy %I_delete_auth on public.%I for delete to authenticated using(true)',t,t); end loop; end $$;
